import { Stepper, type StepperChangeDetail, type StepperNavigateDetail, type StepperStep } from '@absoluteui/components/stepper';

const host = document.querySelector<HTMLElement>('#signup-steps');
const form = document.querySelector<HTMLFormElement>('#signup-form');
const next = document.querySelector<HTMLButtonElement>('#signup-next');
if (host && form && next) {
  let steps: StepperStep[] = [
    { id: 'account', label: 'Account' },
    { id: 'profile', label: 'Profile', description: 'Name and photo' },
    { id: 'finish', label: 'Finish' },
  ];
  const stepper = Stepper.create(host, { label: 'Sign-up steps', steps });
  form.dataset.step = stepper.value;
  // Guard forward moves: the current section must be valid first.
  host.addEventListener('aui-navigate', (event) => {
    const { index, previous } = (event as CustomEvent<StepperNavigateDetail>).detail;
    const from = steps.findIndex((s) => s.id === previous);
    if (index > from && !form.reportValidity()) event.preventDefault();
  });
  host.addEventListener('aui-change', (event) => {
    form.dataset.step = (event as CustomEvent<StepperChangeDetail>).detail.value;
  });
  // "Next": mark the current step complete (unlocking the next one) and move on.
  next.addEventListener('click', () => {
    if (!form.reportValidity()) return;
    const index = steps.findIndex((s) => s.id === stepper.value);
    steps = steps.map((s, i): StepperStep => (i === index ? { ...s, status: 'complete' } : s));
    const following = steps[index + 1];
    stepper.update({ steps, ...(following ? { value: following.id } : {}) });
    form.dataset.step = stepper.value;
  });
}

import { Stepper } from '@absoluteui/components/stepper';

const host = document.querySelector<HTMLElement>('#application-steps');
if (host) {
  const stepper = Stepper.create(host, {
    label: 'Application sections',
    orientation: 'vertical',
    linear: false,
    steps: [
      { id: 'personal', label: 'Personal details', href: '/apply/personal', status: 'complete' },
      { id: 'income', label: 'Income', href: '/apply/income', status: 'error', description: '2 fields need attention' },
      { id: 'documents', label: 'Documents', href: '/apply/documents' },
      { id: 'submit', label: 'Submit', href: '/apply/submit', disabled: true },
    ],
    value: 'documents',
  });
  host.dataset.canSubmit = String(stepper.isReachable('submit'));
}
